def card(work):
    trans = str.maketrans('٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹', '01234567890123456789')

    def check_phone(s):
        d = s.translate(trans).replace(' ', '').replace('-', '')
        if d.startswith('+966'):
            d = '0' + d[4:]
        return d if d.isdigit() and len(d) == 10 and d.startswith('05') else None

    def luhn(n):
        n = n.translate(trans)
        if not n.isdigit():
            return False
        tot = 0
        for i, ch in enumerate(reversed(n)):
            k = int(ch) * (2 if i % 2 else 1)
            tot += k - 9 if k > 9 else k
        return tot % 10 == 0
    ocr = {'phone_ok': '٠٥٥١٢٣٤٥٦٧', 'phone_garbage': '٠٥٥l٢3٤ه٦٧', 'card_ok': '٤٥٣٩١٤٨٨٠٣٤٣٦٤٦٧', 'card_bad': '٤٥٣٩١٤٨٨٠٣٤٣٦٤٦٨'}
    res = {'phone_ok': check_phone(ocr['phone_ok']), 'phone_garbage': check_phone(ocr['phone_garbage']), 'card_ok': luhn(ocr['card_ok']), 'card_bad': luhn(ocr['card_bad'])}
    jwrite(work, 'number_checks.json', {'ocr': ocr, 'result': res, 'ask_user_to_confirm': [k for k, v in res.items() if not v]})
    return [chk('Arabic-Indic phone normalised and valid', res['phone_ok'] == '0551234567', res['phone_ok']), chk('garbled OCR phone rejected', res['phone_garbage'] is None, res['phone_garbage']), chk('Luhn passes the true number', res['card_ok'], res['card_ok']), chk('one-digit OCR error caught by checksum', not res['card_bad'], res['card_bad'])]

