def card(work):

    def multiply(b, s):
        return b * s

    def screen(b, s):
        return b + s - b * s

    def hard_light(b, s):
        return np.where(s <= 0.5, multiply(b, 2 * s), screen(b, 2 * s - 1))

    def overlay(b, s):
        return hard_light(s, b)

    def soft_light(b, s):
        d = np.where(b <= 0.25, ((16 * b - 12) * b + 4) * b, np.sqrt(b))
        return np.where(s <= 0.5, b - (1 - 2 * s) * b * (1 - b), b + (2 * s - 1) * (d - b))

    def difference(b, s):
        return np.abs(b - s)

    def color_dodge(b, s):
        return np.where(b == 0, 0, np.where(s >= 1, 1, np.minimum(1, b / np.maximum(1 - s, 1e-12))))
    b, s = (np.array(0.5), np.array(0.25))
    res = {'multiply': float(multiply(b, s)), 'screen': float(screen(b, s)), 'overlay': float(overlay(b, s)), 'soft_light': float(soft_light(np.array(0.2), np.array(0.8))), 'difference': float(difference(b, s)), 'color_dodge': float(color_dodge(np.array(0.4), np.array(0.5)))}
    grad = np.linspace(0, 1, 256)
    img = (np.stack([multiply(grad, grad[::-1]), screen(grad, grad[::-1]), overlay(grad, grad[::-1])]) * 255).astype(np.uint8)
    Image.fromarray(np.repeat(img, 20, 0)).save(work / 'blends.png')
    jwrite(work, 'blends.json', res)
    sl = 0.2 + (2 * 0.8 - 1) * (((16 * 0.2 - 12) * 0.2 + 4) * 0.2 - 0.2)
    return [chk('multiply 0.5*0.25 = 0.125', res['multiply'] == 0.125, res['multiply']), chk('screen = 0.625', res['screen'] == 0.625, res['screen']), chk('overlay(0.5, 0.25) = hardlight(0.25, 0.5) = 0.25', res['overlay'] == 0.25, res['overlay']), chk('soft-light W3C branch b<=.25', near(res['soft_light'], sl, 1e-12), res['soft_light']), chk('color-dodge 0.4/(1-0.5) = 0.8', near(res['color_dodge'], 0.8, 1e-12), res['color_dodge']), chk('screen of white is white, multiply by black is black', float(screen(np.array(1.0), np.array(0.3))) == 1.0 and float(multiply(np.array(0.7), np.array(0.0))) == 0.0, 'identities')]
